def apply_inventory_ui(destination: Path) -> None:
    """Verify all before/after bytes; apply only to a freshly extracted source tree."""
    manifest_file = destination / 'RELEASE_FILES.json'
    manifest_bytes = manifest_file.read_bytes()
    manifest = json.loads(manifest_bytes)
    if manifest.get('format') != 'aj-release-files-1' or manifest.get('version') != '1.34.19':
        raise ValueError('Workspace UI65 requires the reviewed 1.34.19 source.')
    if (destination / 'UI_PATCH.json').exists():
        raise ValueError('An overlay is already present; start from the verified original parts.')
    prepared = {}
    for name, record in _UI_FILES.items():
        path = destination / name
        expected = record['before_sha256']
        if expected is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('New overlay resource unexpectedly exists: ' + name)
        elif manifest['files'].get(name) != expected or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Workspace UI65 base-file mismatch: ' + name)
        decompressor = zlib.decompressobj()
        content = decompressor.decompress(base64.b64decode(record['zlib_base64'], validate=True), record['bytes'] + 1)
        if (not decompressor.eof or decompressor.unused_data or len(content) != record['bytes']
                or hashlib.sha256(content).hexdigest() != record['after_sha256']):
            raise ValueError('Workspace UI65 payload integrity failure: ' + name)
        prepared[name] = content
    for name, content in prepared.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        manifest['files'][name] = _UI_FILES[name]['after_sha256']
    provenance = {
        'format': 'wavelink-source-overlay-1',
        'patch_id': UI_PATCH_ID,
        'upstream_version': '1.34.19',
        'upstream_archive_sha256': SOURCE_SHA256,
        'upstream_release_manifest_sha256': hashlib.sha256(manifest_bytes).hexdigest(),
        'includes': ['workspace-ui64-membership-access-2026-09-29', 'workspace-ui63-personal-home-workspaces-2026-09-29', 'workspace-ui62-administration-logistics-branding-2026-09-29', 'workspace-ui61-original-files-workflow-2026-09-28', 'workspace-ui60-shared-interface-2026-09-28', 'workspace-ui59-participation-consistency-2026-09-28', 'workspace-ui58-explicit-shift-permissions-2026-09-28', 'workspace-ui57-shift-workspaces-2026-09-28', 'workspace-ui56-certificate-register-2026-09-28', 'workspace-ui55-shared-refresh-stability-2026-09-28', 'workspace-ui54-maintenance-workflow-2026-09-27', 'workspace-ui53-inventory-workflow-2026-09-27', 'workspace-ui52-optional-handover-notes-2026-09-27', 'workspace-ui51-calendar-navigation-stability-2026-09-27', 'workspace-ui50-handover-continuation-navigation-2026-09-27', 'workspace-ui49-logbook-workflow-stability-2026-09-27', 'workspace-ui48-checklists-stable-refresh-2026-09-27', 'workspace-ui47-tasks-workflow-2026-09-27', 'workspace-ui46-work-focused-home-2026-09-27', 'workspace-ui45-builders-session-exit-2026-09-27', 'workspace-ui44-company-builders-imports-2026-09-26', 'workspace-ui43-handover-days-creation-journal-2026-09-26', 'workspace-ui42-home-workspace-discovery-2026-09-26', 'workspace-ui41-visible-actions-help-local-work-2026-09-26', 'workspace-ui40-grouped-reporting-followup-2026-09-26', 'workspace-ui39-simple-toolbox-conduct-2026-09-26', 'workspace-ui38-simple-task-entry-2026-09-26', 'workspace-ui37-simple-certificate-register-2026-09-26', 'workspace-ui36-simple-maintenance-recording-2026-09-26', 'workspace-ui35-signing-pdf-reports-2026-09-26', 'workspace-ui34-document-qr-visitors-2026-09-26', 'workspace-ui33-people-handover-files-routine-saves-2026-09-26', 'workspace-ui32-simple-draft-overview-2026-09-26', 'workspace-ui31-presence-originals-website-icons-2026-09-26', 'workspace-ui30-support-contact-2026-09-26', 'inventory-ui01-2026-09-24', 'inventory-ui02-2026-09-24', 'inventory-ui03-2026-09-24', 'inventory-ui04-2026-09-25', 'workspace-ui05-2026-09-25', 'workspace-ui06-2026-09-25', 'workspace-ui07-2026-09-25', 'workspace-ui08-2026-09-25', 'workspace-ui09-2026-09-25', 'workspace-ui10-2026-09-25', 'workspace-ui11-2026-09-25', 'workspace-ui12-2026-09-25', 'workspace-ui13-2026-09-25', 'workspace-ui14-2026-09-25', 'workspace-ui15-2026-09-25', 'workspace-ui16-2026-09-25', 'workspace-ui17-2026-09-25', 'workspace-ui18-2026-09-25', 'workspace-ui19-uploaded-ui18-2026-09-25', 'workspace-ui20-handover-schedules-2026-09-25', 'workspace-ui21-handover-saved-day-2026-09-25', 'workspace-ui22-handover-guided-review-2026-09-25', 'workspace-ui23-handover-notes-reference-2026-09-25', 'workspace-ui24-handover-draft-workflow-bundle-2026-09-25', 'workspace-ui25-incoming-publication-workflow-2026-09-25', 'workspace-ui26-publication-history-comparison-2026-09-26', 'workspace-ui27-author-recipient-review-2026-09-26', 'workspace-ui28-guided-source-preparation-2026-09-26', 'workspace-ui29-simple-assigned-daily-handovers-2026-09-26'],
        'scope': 'Versioned company job-role presets; exact invitation access snapshots; verified pre-authorised activation; legacy/proposal-only no-access Pending path; bounded department task-management scopes.',
        'data_changes': 'Membership policy schema v2 adds role presets/revisions, invitation proposal snapshots, assigned member roles and bounded management scopes transactionally. Existing accounts, policies, invitations and audit rows are preserved; UI64 invitations remain Pending. Keep UI65+ for this schema.',
        'source_parent_extractor_sha256': '815a635818cb4268957c090e091dab50a95c72b1b6e0bc9f103276fdc630ae09',
        'source_parent_variant': 'verified UI64 + Company C01 + G01 reconstructed from supplied repository; repository baseline also retains Mail Startup M01',
        'mail_startup_m01': 'Preserved by the unchanged deploy/company_entrypoint.py repository launcher; not embedded in the runtime overlay.',
        'changed_files': {name: {key: val for key, val in record.items() if key != 'zlib_base64'} for name, record in _UI_FILES.items()},
    }
    content = (json.dumps(provenance, indent=2) + '\n').encode()
    (destination / 'UI_PATCH.json').write_bytes(content)
    manifest['variant'] = UI_PATCH_ID
    manifest['files']['UI_PATCH.json'] = hashlib.sha256(content).hexdigest()
    manifest_file.write_text(json.dumps(manifest, indent=2) + '\n')
    for name, expected in manifest['files'].items():
        if hashlib.sha256((destination / name).read_bytes()).hexdigest() != expected:
            raise ValueError('Derived source integrity failure: ' + name)


