def apply_integrated_shell_ui73(destination: Path) -> None:
    """Integrate project identity, activity and install access into the permanent shell."""
    manifest_file = destination / 'RELEASE_FILES.json'
    manifest = json.loads(manifest_file.read_text())
    if (manifest.get('format') != 'aj-release-files-1'
            or manifest.get('version') != '1.34.19'
            or manifest.get('variant') != UI72_PATCH_ID):
        raise ValueError('Workspace UI73 requires the exact verified UI72 parent.')
    parent_file = destination / 'UI_PATCH.json'
    parent_bytes = parent_file.read_bytes()
    if hashlib.sha256(parent_bytes).hexdigest() != '47475090ddbc34367d5a298951611de0e9bf3179e3ce5f4504c640ddb9c27b2c':
        raise ValueError('Workspace UI73 parent-overlay mismatch.')
    parent = json.loads(parent_bytes)
    if parent.get('patch_id') != UI72_PATCH_ID:
        raise ValueError('Workspace UI73 parent patch identity mismatch.')
    prepared = {}
    for name, record in _UI73_FILES.items():
        path = destination / name
        expected = record['before_sha256']
        if expected is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('New UI73 resource unexpectedly exists: ' + name)
        elif (manifest['files'].get(name) != expected
              or not path.is_file()
              or hashlib.sha256(path.read_bytes()).hexdigest() != expected):
            raise ValueError('Workspace UI73 base-file mismatch: ' + name)
        decompressor = zlib.decompressobj()
        content = decompressor.decompress(
            base64.b64decode(record['zlib_base64'], validate=True), record['bytes'] + 1)
        content += decompressor.flush()
        if (not decompressor.eof or decompressor.unused_data or decompressor.unconsumed_tail
                or len(content) != record['bytes']
                or hashlib.sha256(content).hexdigest() != record['after_sha256']):
            raise ValueError('Workspace UI73 payload integrity failure: ' + name)
        prepared[name] = content
    for name, content in prepared.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        manifest['files'][name] = _UI73_FILES[name]['after_sha256']
    inherited = list(parent.get('includes') or [])
    if UI72_PATCH_ID not in inherited:
        inherited.append(UI72_PATCH_ID)
    provenance = {
        'format': 'wavelink-source-overlay-1',
        'patch_id': UI73_PATCH_ID,
        'parent_patch_id': UI72_PATCH_ID,
        'parent_overlay_sha256': '47475090ddbc34367d5a298951611de0e9bf3179e3ce5f4504c640ddb9c27b2c',
        'upstream_version': '1.34.19',
        'upstream_archive_sha256': SOURCE_SHA256,
        'includes': inherited,
        'scope': 'Aggressive integrated-shell cleanup. Current project identity, recent project activity, separate-log status and install access now live inside the permanent sidebar. The old standalone project, install and Fleet context bands are absent from the active documents.',
        'data_changes': 'No database, account, permission, invitation, recognition, operational API or workflow-state migration. This cutover changes only the application shell, placement of existing status controls and related browser presentation.',
        'source_parent_extractor_sha256': '3393a54c21b87525dd88305be8d869e4eb2eba652a1770dc0d6aa8376eecd82f',
        'source_parent_variant': UI72_PATCH_ID,
        'interaction_boundary': 'The UI73 layer does not create or move operational controls after route paint. Save status mounts once before the content root and begins hidden; project activity remains read-only and now checks on its 30-second protocol interval rather than a one-second wake-up.',
        'flicker_boundary': 'The standalone app-install-strip, project-strip and fleet-context nodes are removed from index.html and fleet.html. Content has one sidebar offset and the current project card is present inside the static shell before route rendering.',
        'responsive_acceptance': 'Desktop 1440 px, phone 390 px and narrow phone 320 px cover main and Fleet contexts. Tested shell/context geometry is stable after route settlement, with no document-level horizontal overflow or legacy context band.',
        'mail_startup_m01': 'Preserved by the unchanged deploy/company_entrypoint.py repository launcher; not embedded in the runtime overlay.',
        'changed_files': {name: {key: val for key, val in record.items() if key != 'zlib_base64'} for name, record in _UI73_FILES.items()},
    }
    content = (json.dumps(provenance, indent=2) + '\n').encode()
    parent_file.write_bytes(content)
    manifest['variant'] = UI73_PATCH_ID
    manifest['files']['UI_PATCH.json'] = hashlib.sha256(content).hexdigest()
    manifest_file.write_text(json.dumps(manifest, indent=2) + '\n')
    for name, expected in manifest['files'].items():
        path = destination / name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Derived UI73 source integrity failure: ' + name)


