def apply_visual_continuity_ui91(destination: Path) -> None:
    """Apply verified UI91 visual continuity and route reliability to exact UI90."""
    manifest_file = destination / 'RELEASE_FILES.json'
    manifest = json.loads(manifest_file.read_text())
    if (manifest.get('format') != 'aj-release-files-1'
            or manifest.get('version') != '1.34.19'
            or manifest.get('variant') != UI90_PATCH_ID):
        raise ValueError('Workspace UI91 requires the exact verified UI90 parent.')
    parent_file = destination / 'UI_PATCH.json'
    parent_bytes = parent_file.read_bytes()
    if hashlib.sha256(parent_bytes).hexdigest() != '259f0ca89927f3cd98f909290353d425ad28f0975a28b22d80f92c7f1b6f4d6b':
        raise ValueError('Workspace UI91 parent-overlay mismatch.')
    parent_record = json.loads(parent_bytes)
    if parent_record.get('patch_id') != UI90_PATCH_ID:
        raise ValueError('Workspace UI91 parent patch identity mismatch.')
    prepared = {}
    for name, record in _UI91_FILES.items():
        path = destination / name
        expected = record['before_sha256']
        if expected is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('New UI91 resource unexpectedly exists: ' + name)
        elif (manifest['files'].get(name) != expected
              or not path.is_file()
              or hashlib.sha256(path.read_bytes()).hexdigest() != expected):
            raise ValueError('Workspace UI91 base-file mismatch: ' + name)
        decompressor = zlib.decompressobj()
        content = decompressor.decompress(base64.b64decode(record['zlib_base64'], validate=True), record['bytes'] + 1)
        content += decompressor.flush()
        if (not decompressor.eof or decompressor.unused_data or decompressor.unconsumed_tail
                or len(content) != record['bytes']
                or hashlib.sha256(content).hexdigest() != record['after_sha256']):
            raise ValueError('Workspace UI91 payload integrity failure: ' + name)
        prepared[name] = content
    for name, content in prepared.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        manifest['files'][name] = _UI91_FILES[name]['after_sha256']
    decompressor = zlib.decompressobj()
    provenance = decompressor.decompress(base64.b64decode(_UI91_PROVENANCE_ZLIB_BASE64, validate=True), 1000000)
    provenance += decompressor.flush()
    if (not decompressor.eof or decompressor.unused_data or decompressor.unconsumed_tail
            or hashlib.sha256(provenance).hexdigest() != _UI91_PROVENANCE_SHA256):
        raise ValueError('Workspace UI91 provenance integrity failure.')
    provenance_record = json.loads(provenance)
    if (provenance_record.get('patch_id') != UI91_PATCH_ID
            or provenance_record.get('parent_patch_id') != UI90_PATCH_ID):
        raise ValueError('Workspace UI91 provenance identity mismatch.')
    parent_file.write_bytes(provenance)
    manifest['variant'] = UI91_PATCH_ID
    manifest['files']['UI_PATCH.json'] = _UI91_PROVENANCE_SHA256
    manifest_file.write_text(json.dumps(manifest, indent=2) + '\n')
    for name, expected in manifest['files'].items():
        path = destination / name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Derived UI91 source integrity failure: ' + name)

